export const SOURCES: Record<string, string> = {
  "server.ts": "/**\n * HARNESS: Copilot Runtime for this harness (the Angular quickstart never shows one for OpenAI Agents:\n * its runtime callout links a guide whose only server is a Next.js route; FINDINGS.md #1).\n * Shape: the Node listener from @copilotkit/runtime/v2/node (standalone Angular quickstart), with an\n * HttpAgent pointed at the OpenAI Agents agent server in ../backend (agent_server.py mounts each agent\n * at /<name>, the quickstart's \"point Copilot Runtime at http://localhost:8000/<agent name>\").\n * Ports: runtime 8290 (doc: 8200), agent 8291 (doc: 8000). Override with PORT / AGENT_URL.\n * `support` resolves to the same agent so doc snippets with agentId=\"support\" run verbatim.\n */\n// quickstart : copilot runtime\nimport { createServer } from \"node:http\";\nimport { CopilotKitIntelligence, CopilotRuntime, InMemoryAgentRunner } from \"@copilotkit/runtime/v2\";\nimport { createCopilotNodeListener } from \"@copilotkit/runtime/v2/node\";\nimport { HttpAgent } from \"@ag-ui/client\";\nimport { authApp } from \"./auth-runtime\"; // HARNESS: Authentication guide hook, served under /auth\nimport { createTranscriptionService } from \"./lib/transcription-service\"; // HARNESS: doc path src/lib/transcription-service.ts (generic /voice page); kept outside the Angular src tree\n\nconst agentUrl =\n  process.env[\"AGENT_URL\"] ?? \"http://localhost:8291/default\"; // HARNESS: OpenAI Agents agent server, port 8291 (doc: 8000)\n\n// quickstart : copilot runtime start\nconst runtime = new CopilotRuntime({\n  agents: {\n    // quickstart : connect selected agent backend\n    default: new HttpAgent({ url: agentUrl }),\n    // chat ui : support agent\n    support: new HttpAgent({ url: agentUrl }),\n    // HARNESS: the Headless Interrupts page injects \"ticketing\", which no page registers or shows; no\n    // page gives an agent that interrupts, so it gets the quickstart agent (FINDINGS.md).\n    ticketing: new HttpAgent({ url: agentUrl }),\n    // HARNESS: Sub-agents page agent (backend/demo_agents/subagents.py, mounted at /subagents).\n    subagents: new HttpAgent({ url: \"http://localhost:8291/subagents\" }),\n  },\n  // a2ui : enable a2ui middleware start\n  a2ui: {},\n  // a2ui : enable a2ui middleware end\n});\n// quickstart : copilot runtime end\n\nconst port = Number(process.env[\"PORT\"] ?? 8290); // HARNESS: runtime port 8290 (doc uses 8200; workspace port plan)\n\n// quickstart : create copilot node listener start\nconst copilotListener = createCopilotNodeListener({\n  runtime,\n  basePath: \"/api/copilotkit\",\n  cors: true,\n});\n// HARNESS: threads pages (Threads Drawer, Headless Threads) need CopilotKit Intelligence; neither page\n// says where its key goes. Mounted under /threads only when CPK_INTELLIGENCE_API_KEY is set (QA-RULES 9a).\ntry { process.loadEnvFile(\".env.intelligence\"); } catch {} // HARNESS: local key file (gitignored); CI passes the env var\nconst threadsListener = process.env[\"CPK_INTELLIGENCE_API_KEY\"]\n  ? createCopilotNodeListener({\n      runtime: new CopilotRuntime({\n        agents: { default: new HttpAgent({ url: agentUrl }), support: new HttpAgent({ url: agentUrl }) },\n        intelligence: new CopilotKitIntelligence({ apiKey: process.env[\"CPK_INTELLIGENCE_API_KEY\"]! }),\n        identifyUser: async () => ({ id: \"oap-angular-qa-user\", name: \"OAP Angular QA\" }), // HARNESS: no auth here\n      }),\n      basePath: \"/api/copilotkit\",\n      cors: true,\n    })\n  : null;\nif (!threadsListener) console.warn(\"CPK_INTELLIGENCE_API_KEY not set: /threads runtime not mounted\");\n\n// HARNESS: Voice page backend, from the generic /voice page's Backend section (its only server is a\n// Next.js route `app/api/copilotkit-voice/[[...slug]]/route.ts`; ported to this Node listener under /voice).\n// The doc's `createBuiltInAgent()` demo helper is replaced by the quickstart agent (\"replace them with your own agent\").\ntry { process.loadEnvFile(\"../backend/.env\"); } catch {} // HARNESS: OpenAI key lives in backend/.env\nprocess.env[\"OPENAI_TRANSCRIPTION_API_KEY\"] ??= process.env[\"OPENAI_API_KEY\"]; // HARNESS: doc's key name, same OpenAI key\nconst voiceRuntime = new CopilotRuntime({\n  agents: { default: new HttpAgent({ url: agentUrl }) },\n  runner: new InMemoryAgentRunner(),\n  transcriptionService: createTranscriptionService(),\n});\nconst voiceListener = createCopilotNodeListener({\n  runtime: voiceRuntime,\n  basePath: \"/api/copilotkit-voice\",\n  cors: true,\n});\n\n// HARNESS: /auth/* goes to the Authentication guide's hooked runtime (auth-runtime.ts).\ncreateServer((req, res) => {\n  if (threadsListener && req.url?.startsWith(\"/threads/\")) {\n    req.url = req.url.slice(\"/threads\".length);\n    threadsListener(req, res);\n    return;\n  }\n  if (req.url?.startsWith(\"/voice/\")) {\n    req.url = req.url.slice(\"/voice\".length);\n    voiceListener(req, res);\n    return;\n  }\n  if (req.url?.startsWith(\"/auth/\")) {\n    req.url = req.url.slice(\"/auth\".length);\n    authApp(req, res);\n    return;\n  }\n  copilotListener(req, res);\n}).listen(port, () => {\n  console.log(\n    `Copilot Runtime listening at http://localhost:${port}/api/copilotkit`,\n  );\n  console.log(`OpenAI Agents agent: ${agentUrl}`);\n});\n// quickstart : create copilot node listener end\n",
  "src/styles.css": "@import 'tailwindcss';\n\n/* Quickstart step \"Import the styles\". Self-contained — the chat renders\n   without any other CSS.\n   https://docs.copilotkit.ai/angular/ag2/quickstart */\n\n/* quickstart : import the styles start */\n@import '@copilotkit/angular/styles.css';\n\n/* ------------------------------------------------------------------ */\n/* Harness chrome tokens                                              */\n/* `--line` and `--muted` are referenced by the A2UI guide's CSS below, */\n/* which does not define them itself.                                  */\n/* ------------------------------------------------------------------ */\n:root {\n  /* Surfaces */\n  --bg: #f4f6fa;\n  --surface: #ffffff;\n  --surface-sunken: #eef1f7;\n\n  /* Text — all AA or better on --surface */\n  --ink: #0d1526;\n  --ink-soft: #33415a;\n  --muted: #5c6a86;\n\n  /* Lines */\n  --line: #e0e5ee;\n  --line-strong: #c6cedd;\n\n  /* Accent */\n  --accent: #4f46e5;\n  --accent-hover: #4338ca;\n  --accent-soft: #eef0ff;\n  --accent-ink: #362fa8;\n\n  /* Code surface */\n  --code-bg: #0b1220;\n  --code-bar: #131c2f;\n  --code-ink: #dbe3f0;\n  --code-line: #24304a;\n}\n\nhtml,\nbody {\n  height: 100%;\n  margin: 0;\n  color: var(--ink);\n  background: var(--bg);\n  font-family:\n    'Inter',\n    -apple-system,\n    BlinkMacSystemFont,\n    'Segoe UI',\n    Roboto,\n    Helvetica,\n    Arial,\n    sans-serif;\n  -webkit-font-smoothing: antialiased;\n}\n\n/* Visible keyboard focus everywhere in the harness chrome (WCAG 2.4.7). */\na:focus-visible,\nbutton:focus-visible,\n[tabindex]:focus-visible {\n  outline: 2px solid var(--accent);\n  outline-offset: 2px;\n  border-radius: 0.375rem;\n}\n\n/* Inline code in prose — distinct from the dark code blocks. */\n.prose-inline-code,\np > code,\nli > code,\ntd > code {\n  padding: 0.1rem 0.35rem;\n  border: 1px solid var(--line);\n  border-radius: 0.3rem;\n  background: var(--surface-sunken);\n  color: var(--accent-ink);\n  font-size: 0.85em;\n}\n\n/* ------------------------------------------------------------------ */\n/* Code figures                                                        */\n/* ------------------------------------------------------------------ */\n.code-figure {\n  overflow: hidden;\n  border: 1px solid var(--code-line);\n  border-radius: 0.75rem;\n  background: var(--code-bg);\n  box-shadow: 0 12px 28px -22px rgb(11 18 32 / 0.65);\n}\n\n/* Quoted-from-docs samples read as secondary to the code that runs. */\n.code-figure--quoted {\n  border-style: dashed;\n  border-color: var(--line-strong);\n}\n\n.code-figure__bar {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.5rem 1rem;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0.5rem 0.85rem;\n  border-bottom: 1px solid var(--code-line);\n  background: var(--code-bar);\n}\n\n.code-figure__path-group {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 0.45rem;\n  min-width: 0;\n}\n\n.code-figure__path {\n  color: #b9c6de;\n  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n  font-size: 0.72rem;\n  word-break: break-all;\n}\n\n.code-figure__copy-path,\n.code-figure__open-ide {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.3rem;\n  padding: 0.12rem 0.45rem;\n  border: 1px solid #2f3d5c;\n  border-radius: 0.35rem;\n  background: #141f33;\n  color: #a5b4cd;\n  font-size: 0.68rem;\n  font-weight: 500;\n  cursor: pointer;\n  text-decoration: none;\n  transition: all 0.15s ease;\n  line-height: 1.2;\n}\n\n.code-figure__copy-path:hover,\n.code-figure__open-ide:hover {\n  background: #22304d;\n  border-color: #3e517a;\n  color: #f1f5f9;\n}\n\n.code-figure__icon {\n  width: 0.85rem;\n  height: 0.85rem;\n  flex-shrink: 0;\n}\n\n.code-figure__meta {\n  display: flex;\n  flex-shrink: 0;\n  gap: 0.5rem;\n  align-items: center;\n}\n\n.code-figure__note {\n  color: #93a3c0;\n  font-size: 0.72rem;\n}\n\n.code-figure__lang,\n.code-figure__badge {\n  padding: 0.1rem 0.45rem;\n  border-radius: 999px;\n  background: #22304d;\n  color: #a9b8d6;\n  font-size: 0.65rem;\n  font-weight: 600;\n  letter-spacing: 0.02em;\n  text-transform: uppercase;\n}\n\n.code-figure__badge {\n  background: #3b2f18;\n  color: #e6c07b;\n}\n\n.code-figure__copy {\n  padding: 0.15rem 0.55rem;\n  border: 1px solid #2f3d5c;\n  border-radius: 0.35rem;\n  background: transparent;\n  color: #b9c6de;\n  font-size: 0.7rem;\n  font-weight: 600;\n  cursor: pointer;\n  transition: background 0.15s ease;\n}\n\n.code-figure__copy:hover {\n  background: #22304d;\n  color: #e6edf9;\n}\n\n.code-figure__pre {\n  max-height: 32rem;\n  margin: 0;\n  overflow: auto;\n  padding: 1rem;\n  color: var(--code-ink);\n  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n  font-size: 0.78rem;\n  line-height: 1.65;\n  tab-size: 2;\n}\n\n/* ------------------------------------------------------------------ */\n/* highlight.js theme — tuned for contrast on --code-bg                */\n/* ------------------------------------------------------------------ */\n.hljs-comment,\n.hljs-quote {\n  color: #8494b3;\n  font-style: italic;\n}\n\n.hljs-keyword,\n.hljs-selector-tag,\n.hljs-literal,\n.hljs-doctag {\n  color: #c4b5fd;\n}\n\n.hljs-string,\n.hljs-regexp,\n.hljs-addition {\n  color: #8ee7a5;\n}\n\n.hljs-number,\n.hljs-symbol,\n.hljs-bullet {\n  color: #fcd34d;\n}\n\n.hljs-title,\n.hljs-title.function_,\n.hljs-section {\n  color: #7dd3fc;\n}\n\n.hljs-title.class_,\n.hljs-type,\n.hljs-built_in,\n.hljs-class .hljs-title {\n  color: #fdba74;\n}\n\n.hljs-attr,\n.hljs-attribute,\n.hljs-property,\n.hljs-variable,\n.hljs-template-variable {\n  color: #f0abfc;\n}\n\n.hljs-name,\n.hljs-selector-id,\n.hljs-selector-class,\n.hljs-tag {\n  color: #fb7185;\n}\n\n.hljs-meta,\n.hljs-params,\n.hljs-punctuation {\n  color: #a5b4cd;\n}\n\n.hljs-deletion {\n  color: #fca5a5;\n}\n\n.hljs-emphasis {\n  font-style: italic;\n}\n\n.hljs-strong {\n  font-weight: 700;\n}\n\n/* chat ui : scope css changes start */\n.support-chat .copilotKitUserMessage {\n  color: white;\n  background: #2563eb;\n  border-radius: 0.75rem;\n}\n\n.support-chat .copilotKitAssistantMessage {\n  padding: 0.75rem;\n  color: #172554;\n  background: #eff6ff;\n  border-radius: 0.75rem;\n}\n/* chat ui : scope css changes end */\n\n/* a2ui : style rendered components start */\n.a2ui-row {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: stretch;\n  width: 100%;\n}\n\n.a2ui-row > * {\n  flex: 1 1 10rem;\n  min-width: 0;\n}\n\n.a2ui-column {\n  display: flex;\n  flex-direction: column;\n  width: 100%;\n}\n\n[data-testid='declarative-card'],\n.a2ui-chart-card,\n.a2ui-flight-card {\n  display: block;\n  padding: 1rem;\n  border: 1px solid var(--line);\n  border-radius: 0.9rem;\n  background: light-dark(white, #191a1e);\n  box-shadow: 0 8px 22px -18px rgb(15 23 42 / 0.4);\n}\n\n.a2ui-metric {\n  display: grid;\n  min-width: 8rem;\n  gap: 0.25rem;\n}\n\n.a2ui-metric > span,\n.a2ui-metric > small {\n  color: light-dark(var(--muted), #adadb2);\n  font-size: 0.75rem;\n}\n\n.a2ui-metric > strong {\n  font-size: 1.4rem;\n}\n\n.a2ui-status,\n.a2ui-airline {\n  display: inline-flex;\n  width: fit-content;\n  padding: 0.25rem 0.55rem;\n  border-radius: 999px;\n  background: light-dark(#eef2ff, rgb(30 27 75 / 40%));\n  font-size: 0.75rem;\n  font-weight: 700;\n}\n\n.a2ui-status-success {\n  background: light-dark(#dcfce7, rgb(5 46 22 / 40%));\n  color: light-dark(#166534, #86efac);\n}\n.a2ui-status-warning {\n  background: light-dark(#fef3c7, rgb(69 26 3 / 40%));\n  color: light-dark(#92400e, #fcd34d);\n}\n.a2ui-status-error {\n  background: light-dark(#fee2e2, rgb(69 10 10 / 40%));\n  color: light-dark(#991b1b, #fca5a5);\n}\n/* a2ui : style rendered components end */\n\n/* inspector : position the launcher start (https://docs.copilotkit.ai/angular/openai-agents-python/inspector, verbatim) */\ncpk-web-inspector {\n  /* The panel is draggable and sets an inline transform. Neutralize it before\n     choosing a corner. */\n  transform: none !important;\n  top: auto !important;\n  bottom: 1rem !important;\n  left: 1rem !important;\n  right: auto !important;\n}\n/* inspector : position the launcher end */\n",
  "src/app/app.config.ts": "import {\n  ApplicationConfig,\n  provideBrowserGlobalErrorListeners,\n} from '@angular/core';\nimport { provideRouter, withInMemoryScrolling } from '@angular/router';\nimport { provideClientHydration } from '@angular/platform-browser';\nimport { provideCopilotKit } from '@copilotkit/angular';\n\nimport { routes } from './app.routes';\n\n\n\n/**\n * One provider at the application root, so a conversation started on any demo\n * route continues on every other route.\n *\n * `runtimeUrl` points at the Copilot Runtime from the quickstart — the\n * supported path, where the browser never talks to the AG2 agent directly.\n * The `HttpAgent` binding that reaches the AG2 AG-UI endpoint lives\n * server-side in frontend/server.ts.\n *\n * `a2ui.recovery` and `openGenerativeUI.sandboxFunctions` are the A2UI and\n * generative-UI guide options. No `a2ui.catalog` is set yet — supplying one is\n * what actually registers the render_a2ui renderer, so A2UI stays inert until\n * a catalog is added. See README known issues.\n */\nexport const appConfig: ApplicationConfig = {\n  providers: [\n    provideBrowserGlobalErrorListeners(),\n    provideRouter(\n      routes,\n      withInMemoryScrolling({ scrollPositionRestoration: 'top' }),\n    ),\n    provideClientHydration(),\n    // quickstart : connect to copilot runtime start\n    provideCopilotKit({\n      runtimeUrl: 'http://localhost:8290/api/copilotkit', // HARNESS: doc says :8200, runtime runs on 8290 (workspace port plan)\n      // a2ui : recover incomplete streams start\n      a2ui: {\n        recovery: { showAfterMs: 2_000, showAfterAttempts: 2 },\n      },\n      // a2ui : recover incomplete streams end\n      // HARNESS: the Frontend tools page's Open Generative UI config (openGenerativeUI with\n      // setDashboardFilter) is kept verbatim in doc-verbatim/frontend-tools/app.config.ts, not here:\n      // registered at the root it gave every page's agent a generateSandboxedUi tool, which on the\n      // Native generative UI demo answered with an empty message instead of text.\n    }),\n    // quickstart : connect to copilot runtime end\n  ],\n};\n",
  "src/app/features/a2ui/a2ui-chat.component.ts": "/**\n * A2UI demo. The page's provider snippet passes `a2ui: { catalog: productCatalog, recovery }`, but\n * `productCatalog` is never defined, and the catalog snippets around it use identifiers the page\n * never defines either (`dynamicString`, `AcmeBadge`, `PanelComponent`, every import). Those files\n * are kept verbatim in frontend/doc-verbatim/a2ui/ (outside src/, so `ng serve` keeps building) and\n * type-checked during the take. HARNESS: this chat runs on the app-root provider, which has the\n * page's `recovery` options and no catalog (the one the page never gives), with the runtime's\n * `a2ui: {}` (frontend/server.ts).\n * https://docs.copilotkit.ai/angular/openai-agents-python/generative-ui/a2ui\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-a2ui-chat',\n  imports: [CopilotChat],\n  template: `<div style=\"height: 100%\"><copilot-chat /></div>`,\n})\nexport class A2uiChatComponent {}\n",
  "src/app/features/attachments/media-chat.component.ts": "// attachments : enable attachments start\n/**\n * \"Enable attachments\", verbatim. Without `onUpload`, files are read as base64\n * and travel inline with the message.\n * https://docs.copilotkit.ai/angular/ag2/guides/threads-memory-attachments-headless\n */\n\nimport { Component } from '@angular/core';\nimport { CopilotChat, type AttachmentsConfig } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-media-chat',\n  imports: [CopilotChat],\n  template: ` <copilot-chat [attachments]=\"attachments\" /> `,\n})\nexport class MediaChatComponent {\n  // attachments : attachments config start\n  protected readonly attachments: AttachmentsConfig = {\n    enabled: true,\n    accept: 'image/*,application/pdf',\n    maxSize: 10 * 1024 * 1024,\n    onUploadFailed: (error) => {\n      console.error(error.reason, error.message);\n    },\n  };\n  // attachments : attachments config end\n}\n// attachments : enable attachments end\n",
  "src/app/features/auth/auth-chat.component.ts": "// auth : update the runtime connection after sign-in start\n/**\n * Authentication guide, \"When sign-in state changes after bootstrap, update the\n * runtime connection through the CopilotKit service\" (verbatim body in `apply`).\n * https://docs.copilotkit.ai/angular/openai-agents-python/auth\n *\n * HARNESS: the guide never defines the session (`readSessionToken()`, `sessionToken`) or the\n * server's `verifySession()`. This demo starts signed out, so requests reach\n * the guide's `onRequest` hook without a token (401), and the \"Sign in\" button sets the\n * Showcase's own `demo-token-123` (the guide's DEMO_AUTH_HEADERS). The chat talks to the runtime\n * mount that runs that hook (frontend/auth-runtime.ts, under /auth on 8290).\n */\nimport { Component, inject, signal } from \"@angular/core\";\nimport { CopilotChat, CopilotKit } from \"@copilotkit/angular\";\n\n@Component({\n  selector: \"app-auth-chat\",\n  imports: [CopilotChat],\n  template: `\n    <div style=\"display: flex; flex-direction: column; height: 100%\">\n      <div style=\"display: flex; gap: 0.75rem; align-items: center; padding: 0.5rem 1rem; border-bottom: 1px solid #e2e8f0\">\n        @if (sessionToken()) {\n          <span>Signed in</span>\n          <button type=\"button\" (click)=\"signOut()\">Sign out</button>\n        } @else {\n          <span>Signed out</span>\n          <button type=\"button\" (click)=\"signIn()\">Sign in</button>\n        }\n      </div>\n      <div style=\"flex: 1; min-height: 0\"><copilot-chat /></div>\n    </div>\n  `,\n})\nexport class AuthChatComponent {\n  private readonly copilotKit = inject(CopilotKit);\n  protected readonly sessionToken = signal<string | null>(null); // HARNESS: the guide's session\n\n  constructor() {\n    this.copilotKit.updateRuntime({ runtimeUrl: \"http://localhost:8290/auth/api/copilotkit\" }); // HARNESS: auth-hook runtime mount\n    this.apply();\n  }\n\n  protected signIn(): void {\n    this.sessionToken.set(\"demo-token-123\"); // HARNESS: the Showcase's DEMO_AUTH_HEADERS token\n    this.apply();\n  }\n\n  protected signOut(): void {\n    this.sessionToken.set(null);\n    this.apply();\n  }\n\n  private apply(): void {\n    const copilotKit = this.copilotKit;\n    const sessionToken = this.sessionToken();\n    // --- verbatim from the doc ---\n    copilotKit.updateRuntime({\n      headers: sessionToken\n        ? { Authorization: `Bearer ${sessionToken}` }\n        : {},\n    });\n    // --- end verbatim ---\n  }\n}\n// auth : update the runtime connection after sign-in end\n",
  "src/app/features/chat-ui/css-demo.component.ts": "/**\n * HARNESS host for CSS Customization\n * (https://docs.copilotkit.ai/angular/openai-agents-python/custom-look-and-feel/css): the page says\n * \"Put a scope class on your feature host\"; the host is the Prebuilt Components inline chat\n * (support-chat.component.ts) and the scope class is the page's `.support-chat`. The CSS block is\n * verbatim in src/styles.css.\n */\nimport { Component } from '@angular/core';\n\nimport { SupportChatComponent } from './support-chat.component';\n\n@Component({\n  selector: 'app-css-demo',\n  imports: [SupportChatComponent],\n  template: `<div class=\"support-chat\" style=\"padding: 1rem; height: 100%\"><app-support-chat /></div>`,\n})\nexport class CssDemoComponent {}\n",
  "src/app/features/chat-ui/custom-assistant-message.component.ts": "// chat ui : replace an assistant message start\n/**\n * \"Replace an assistant message\", verbatim.\n * https://docs.copilotkit.ai/angular/ag2/guides/chat-ui\n */\n\nimport { ChangeDetectionStrategy, Component, input } from '@angular/core';\n\ntype AssistantMessage = {\n  id: string;\n  role: 'assistant';\n  content?: string;\n};\n\n@Component({\n  selector: 'app-custom-assistant-message',\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  template: `\n    <article class=\"answer\">\n      <span class=\"answer__label\">Assistant</span>\n      <p>{{ message().content }}</p>\n    </article>\n  `,\n})\nexport class CustomAssistantMessageComponent {\n  readonly message = input.required<AssistantMessage>();\n}\n// chat ui : replace an assistant message end\n",
  "src/app/features/chat-ui/custom-message-chat.component.ts": "// chat ui : replace an assistant message component start\n/**\n * The second `SupportChatComponent` from \"Replace an assistant message\",\n * verbatim except for the class name and selector — the guide gives two\n * different components the same name and selector, and both are mounted here.\n * https://docs.copilotkit.ai/angular/ag2/guides/chat-ui\n */\n\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\nimport { CustomAssistantMessageComponent } from './custom-assistant-message.component';\n\n@Component({\n  selector: 'app-custom-message-chat',\n  imports: [CopilotChat],\n  template: `\n    <copilot-chat\n      [assistantMessageComponent]=\"assistantMessageComponent\"\n      assistantMessageClass=\"support-answer\"\n    />\n  `,\n})\nexport class CustomMessageChatComponent {\n  protected readonly assistantMessageComponent =\n    CustomAssistantMessageComponent;\n}\n// chat ui : replace an assistant message component end\n",
  "src/app/features/chat-ui/popup-sidebar.component.ts": "// chat ui : use a popup or sidebar start\n/**\n * \"Use a popup or sidebar\", verbatim except for the class name and selector\n * (the guide mounts it as `AppComponent` / `app-root`).\n * https://docs.copilotkit.ai/angular/ag2/guides/chat-ui\n */\n\nimport { Component, signal } from '@angular/core';\nimport { CopilotPopup, CopilotSidebar } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-popup-sidebar',\n  imports: [CopilotPopup, CopilotSidebar],\n  template: `\n    <copilot-popup\n      [(open)]=\"popupOpen\"\n      title=\"Support assistant\"\n      [clickOutsideToClose]=\"true\"\n    />\n\n    <copilot-sidebar\n      [(open)]=\"sidebarOpen\"\n      mode=\"docked\"\n      position=\"right\"\n      title=\"Workspace assistant\"\n      [width]=\"480\"\n    />\n  `,\n})\nexport class PopupSidebarComponent {\n  readonly popupOpen = signal(false);\n  readonly sidebarOpen = signal(false);\n}\n// chat ui : use a popup or sidebar end\n",
  "src/app/features/chat-ui/prebuilt-demo.component.ts": "/**\n * HARNESS host for the Prebuilt Components page\n * (https://docs.copilotkit.ai/angular/openai-agents-python/prebuilt-components): the page's inline\n * chat (support-chat.component.ts) and its popup + sidebar component (popup-sidebar.component.ts,\n * the page's `AppComponent`), both verbatim, mounted together as the page shows them.\n */\nimport { Component } from '@angular/core';\n\nimport { PopupSidebarComponent } from './popup-sidebar.component';\nimport { SupportChatComponent } from './support-chat.component';\n\n@Component({\n  selector: 'app-prebuilt-demo',\n  imports: [SupportChatComponent, PopupSidebarComponent],\n  template: `\n    <div style=\"padding: 1rem; height: 100%\"><app-support-chat /></div>\n    <app-popup-sidebar />\n  `,\n})\nexport class PrebuiltDemoComponent {}\n",
  "src/app/features/chat-ui/support-chat.component.ts": "// chat ui : add an inline chat start\n/**\n * \"Add an inline chat\", verbatim.\n * https://docs.copilotkit.ai/angular/ag2/guides/chat-ui\n *\n * `agentId=\"support\"` resolves because the runtime registers a `support` agent\n * alongside `default` (see frontend/server.ts).\n */\n\nimport { ChangeDetectionStrategy, Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-support-chat',\n  imports: [CopilotChat],\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  template: `\n    <section class=\"chat-shell\" aria-label=\"Support assistant\">\n      <copilot-chat agentId=\"support\" />\n    </section>\n  `,\n  styles: `\n    .chat-shell {\n      height: min(48rem, 80vh);\n      overflow: hidden;\n      border: 1px solid #dbe3eb;\n      border-radius: 1rem;\n    }\n  `,\n})\nexport class SupportChatComponent {}\n// chat ui : add an inline chat end\n",
  "src/app/features/gen-ui-tool-based/incident-card.component.ts": "// components as tools : let the agent display one of your components start\n/**\n * \"Let the agent display one of your components\", verbatim.\n * https://docs.copilotkit.ai/angular/openai-agents-python/generative-ui/tool-based\n */\n\nimport { Component, input } from \"@angular/core\";\nimport { AngularToolCall, ToolRenderer } from \"@copilotkit/angular\";\n\ntype IncidentArgs = { id: string; severity: string };\n\n@Component({\n  selector: \"app-incident-card\",\n  standalone: true,\n  template: `\n    @let call = toolCall();\n    @if (call.status === \"in-progress\") {\n      <p>Loading incident…</p>\n    } @else {\n      <article>\n        <strong>{{ call.args.id }}</strong>\n        <span>{{ call.args.severity }}</span>\n      </article>\n    }\n  `,\n})\nexport class IncidentCardComponent implements ToolRenderer<IncidentArgs> {\n  readonly toolCall = input.required<AngularToolCall<IncidentArgs>>();\n}\n// components as tools : let the agent display one of your components end\n",
  "src/app/features/gen-ui-tool-based/tool-based-chat.component.ts": "/**\n * Components as Tools demo. The page's `registerComponent` snippet, verbatim, in a component\n * constructor (an injection context).\n * https://docs.copilotkit.ai/angular/openai-agents-python/generative-ui/tool-based\n */\nimport { Component } from '@angular/core'; // HARNESS: the page shows the call without a host component\nimport { CopilotChat, registerComponent } from '@copilotkit/angular'; // HARNESS: the snippet has no imports\nimport { z } from 'zod'; // HARNESS: the snippet has no imports\n\nimport { IncidentCardComponent } from './incident-card.component';\n\n@Component({\n  selector: 'app-tool-based-chat',\n  imports: [CopilotChat],\n  template: `<div style=\"height: 100%\"><copilot-chat /></div>`,\n})\nexport class ToolBasedChatComponent {\n  constructor() {\n    // components as tools : register component start\n    registerComponent({\n      name: \"show_incident\",\n      description: \"Show one incident from the incident table.\",\n      parameters: z.object({\n        id: z.string().describe(\"The incident id, such as INC-4711\"),\n        severity: z.string().describe(\"One of sev1, sev2, sev3\"),\n      }),\n      component: IncidentCardComponent,\n    });\n    // components as tools : register component end\n  }\n}\n",
  "src/app/features/gen-ui-tool-rendering/tool-rendering-chat.component.ts": "/**\n * Tool Call Rendering demo. The page's `registerFrontendTool` snippet (\"Pass the class as\n * `component` when the tool runs in the browser\"), verbatim, in a component constructor.\n * The `registerRenderToolCall` snippet is the alternative for a server-side `getWeather`;\n * the two register the same tool name, so only the browser variant is mounted (the OpenAI Agents\n * agent has no getWeather tool, and the page shows no backend for one).\n * https://docs.copilotkit.ai/angular/openai-agents-python/generative-ui/tool-rendering\n */\nimport { Component } from '@angular/core'; // HARNESS: the page shows the call without a host component\nimport { CopilotChat, registerFrontendTool } from '@copilotkit/angular'; // HARNESS: the snippet has no imports\nimport { z } from 'zod'; // HARNESS: the snippet has no imports\n\nimport { WeatherCardComponent } from './weather-card.component';\n\n@Component({\n  selector: 'app-tool-rendering-chat',\n  imports: [CopilotChat],\n  template: `<div style=\"height: 100%\"><copilot-chat /></div>`,\n})\nexport class ToolRenderingChatComponent {\n  constructor() {\n    // tool rendering : register frontend tool with component start\n    registerFrontendTool({\n      name: \"getWeather\",\n      description: \"Get the current weather for a city\",\n      parameters: z.object({ city: z.string() }),\n      component: WeatherCardComponent,\n      handler: async ({ city }, { signal }) => {\n        const response = await fetch(`/api/weather?city=${encodeURIComponent(city)}`, {\n          signal,\n        });\n        return response.text();\n      },\n    });\n    // tool rendering : register frontend tool with component end\n  }\n}\n",
  "src/app/features/gen-ui-tool-rendering/weather-card.component.ts": "// src/app/weather-card.component.ts on the page (Tool Call Rendering, \"Render a tool result\"), verbatim.\n// https://docs.copilotkit.ai/angular/openai-agents-python/generative-ui/tool-rendering\nimport { Component, input } from \"@angular/core\";\nimport {\n  type AngularToolCall,\n  type ToolRenderer,\n} from \"@copilotkit/angular\";\n\ntype WeatherArgs = { city: string };\n\n@Component({\n  selector: \"app-weather-card\",\n  template: `\n    @let call = toolCall();\n    @if (call.status === \"complete\") {\n      <article>\n        <strong>{{ call.args.city }}</strong>\n        <p>{{ call.result }}</p>\n      </article>\n    } @else {\n      <p>Loading weather for {{ call.args.city ?? \"…\" }}</p>\n    }\n  `,\n})\nexport class WeatherCardComponent implements ToolRenderer<WeatherArgs> {\n  readonly toolCall = input.required<AngularToolCall<WeatherArgs>>();\n}\n",
  "src/app/features/headless-threads/headless-threads-demo.component.ts": "/**\r\n * HARNESS host for the Headless Threads page\r\n * (https://docs.copilotkit.ai/angular/openai-agents-python/headless-threads).\r\n * The page gives `<copilot-chat agentId=\"support\" [threadId]=\"selectedThreadId()\" />` with no\r\n * component around it and never defines `selectedThreadId`; this host supplies that signal\r\n * (HARNESS) and mounts the verbatim ThreadListComponent (features/threads/thread-list.component.ts)\r\n * beside it.\r\n */\r\nimport { Component, inject, signal } from '@angular/core';\r\nimport { CopilotChat, CopilotKit } from '@copilotkit/angular';\r\n\r\nimport { ThreadListComponent } from '../threads/thread-list.component';\r\n\r\n@Component({\r\n  selector: 'app-headless-threads-demo',\r\n  imports: [CopilotChat, ThreadListComponent],\r\n  template: `\r\n    <div style=\"display: flex; height: 100%\">\r\n      <aside style=\"width: 18rem; padding: 1rem; border-right: 1px solid #e2e8f0; display: flex; flex-direction: column; gap: 0.5rem\">\r\n        <app-thread-list />\r\n      </aside>\r\n      <div style=\"flex: 1; min-width: 0\">\r\n        <!-- headless threads : resume a specific thread (verbatim) -->\r\n        <copilot-chat agentId=\"support\" [threadId]=\"selectedThreadId()\" />\r\n      </div>\r\n    </div>\r\n  `,\r\n})\r\nexport class HeadlessThreadsDemoComponent {\r\n  readonly selectedThreadId = signal<string | undefined>(undefined); // HARNESS: never defined on the page\r\n  constructor() {\r\n    // HARNESS: the page never says threads need a CopilotKit Intelligence runtime; frontend/server.ts serves one under /threads.\r\n    inject(CopilotKit).updateRuntime({ runtimeUrl: 'http://localhost:8290/threads/api/copilotkit' });\r\n  }\r\n}\r\n",
  "src/app/features/hitl/approval-card.component.ts": "// human in the loop : register a decision tool renderer start\n/**\n * \"Register a decision tool\" renderer, verbatim.\n * https://docs.copilotkit.ai/angular/openai-agents-python/human-in-the-loop\n */\n\nimport { Component, input } from '@angular/core';\nimport {\n  type HumanInTheLoopToolCall,\n  type HumanInTheLoopToolRenderer,\n} from '@copilotkit/angular';\n\ntype ApprovalArgs = {\n  action: string;\n  reason: string;\n};\n\n@Component({\n  selector: 'app-approval-card',\n  template: `\n    @let call = toolCall();\n    <article>\n      <h3>Approve {{ call.args.action ?? \"this action\" }}?</h3>\n      <p>{{ call.args.reason }}</p>\n\n      @if (call.status !== \"complete\") {\n        <button type=\"button\" (click)=\"call.respond({ approved: true })\">\n          Approve\n        </button>\n        <button type=\"button\" (click)=\"call.respond({ approved: false })\">\n          Reject\n        </button>\n      }\n    </article>\n  `,\n})\nexport class ApprovalCardComponent\n  implements HumanInTheLoopToolRenderer<ApprovalArgs>\n{\n  readonly toolCall = input.required<HumanInTheLoopToolCall<ApprovalArgs>>();\n}\n// human in the loop : register a decision tool renderer end\n",
  "src/app/features/hitl/approval-tools.service.ts": "// human in the loop : register a decision tool service start\n/**\n * \"Register the tool from the component or service that owns the decision UI\",\n * verbatim. There is no handler — CopilotKit supplies one that waits for\n * `respond`, returns the decision to the agent, and continues the run.\n * https://docs.copilotkit.ai/angular/openai-agents-python/human-in-the-loop\n */\n\nimport { Injectable } from '@angular/core';\nimport { registerHumanInTheLoop } from '@copilotkit/angular';\nimport { z } from 'zod';\n\nimport { ApprovalCardComponent } from './approval-card.component';\n\n@Injectable()\nexport class ApprovalToolsService {\n  constructor() {\n    // human in the loop : register human in the loop tool start\n    registerHumanInTheLoop({\n      name: 'requestApproval',\n      description: 'Ask the user before a consequential action',\n      parameters: z.object({\n        action: z.string(),\n        reason: z.string(),\n      }),\n      component: ApprovalCardComponent,\n    });\n    // human in the loop : register human in the loop tool end\n  }\n}\n// human in the loop : register a decision tool service end\n",
  "src/app/features/hitl/headless-interrupts-chat.component.ts": "/**\n * HARNESS: Headless Interrupts demo. The page's TicketApprovalComponent (verbatim, agent \"ticketing\")\n * above a chat on the same agent. The page shows no chat and no backend; \"ticketing\" is the harness\n * interrupt agent registered in frontend/server.ts.\n * https://docs.copilotkit.ai/angular/openai-agents-python/human-in-the-loop/headless\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\nimport { TicketApprovalComponent } from './ticket-approval.component';\n\n@Component({\n  selector: 'app-headless-interrupts-chat',\n  imports: [CopilotChat, TicketApprovalComponent],\n  template: `\n    <div style=\"display: flex; flex-direction: column; height: 100%\">\n      <div style=\"padding: 0.75rem 1rem\"><app-ticket-approval /></div>\n      <div style=\"flex: 1; min-height: 0\"><copilot-chat agentId=\"ticketing\" /></div>\n    </div>\n  `,\n})\nexport class HeadlessInterruptsChatComponent {}\n",
  "src/app/features/hitl/hitl-chat.component.ts": "// human in the loop : hitl chat start\n/**\n * HITL Overview demo: the decision tool (ApprovalToolsService, verbatim) rendered in the chat's\n * tool-call flow. Injecting ApprovalToolsService is what constructs it, and construction performs\n * the `registerHumanInTheLoop` call. HARNESS: the page never shows where the service is provided.\n * https://docs.copilotkit.ai/angular/openai-agents-python/human-in-the-loop\n */\n\nimport { Component, inject } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\nimport { ApprovalToolsService } from './approval-tools.service';\n\n@Component({\n  selector: 'app-hitl-chat',\n  imports: [CopilotChat],\n  providers: [ApprovalToolsService], // HARNESS: the page says \"register from the component or service\", shows no providers\n  template: `\n    <div style=\"height: 100%\">\n      <copilot-chat />\n    </div>\n  `,\n})\nexport class HitlChatComponent {\n  private readonly approvalTools = inject(ApprovalToolsService); // HARNESS\n}\n// human in the loop : hitl chat end\n",
  "src/app/features/hitl/interrupt-panel.component.ts": "// human in the loop : handle an interrupt start\n/**\n * \"Handle an interrupt\", verbatim. The controller is headless, so this panel\n * renders nothing until the backend emits an AG-UI interrupt.\n * https://docs.copilotkit.ai/angular/openai-agents-python/human-in-the-loop/useInterrupt\n */\n\nimport { Component } from '@angular/core';\nimport { injectInterrupt } from '@copilotkit/angular';\n\ntype ReviewRequest = {\n  title?: string;\n  choices?: Array<{ id: string; label: string }>;\n};\n\n@Component({\n  selector: 'app-interrupt-panel',\n  template: `\n    @if (controller.event(); as event) {\n      @let request = asReviewRequest(event.value);\n      <section aria-labelledby=\"review-title\">\n        <h2 id=\"review-title\">{{ request.title ?? \"Review required\" }}</h2>\n\n        @for (choice of request.choices ?? []; track choice.id) {\n          <button type=\"button\" (click)=\"resolve(choice.id)\">\n            {{ choice.label }}\n          </button>\n        }\n\n        <button type=\"button\" (click)=\"cancel()\">Cancel</button>\n      </section>\n    }\n\n    @if (controller.error()) {\n      <p role=\"alert\">The decision could not be submitted.</p>\n    }\n  `,\n})\nexport class InterruptPanelComponent {\n  // DIVERGENCE RESOLVED at @copilotkit/angular@0.4.0 — the doc's own form runs.\n  //\n  // The doc's snippet passes the agent id as a string:\n  //\n  //     injectInterrupt<ReviewRequest>('default');\n  //\n  // That did not compile against @copilotkit/angular@0.3.1, whose declaration\n  // took an options object and had no string overload:\n  //\n  //     declare function injectInterrupt<TValue, TResult>(\n  //       options?: InjectInterruptOptions<TValue, TResult>\n  //     ): InterruptController<TValue, TResult>;\n  //\n  //   TS2559: Type '\"default\"' has no properties in common with type\n  //           'InjectInterruptOptions<ReviewRequest, never>'\n  //\n  // This file carried the object form for as long as that was true, because one\n  // compile error blocks every recording, not just this page. 0.4.0 publishes\n  // the string-first overload:\n  //\n  //     declare function injectInterrupt<TValue, TResult>(\n  //       agentId?: InterruptAgentId,\n  //       options?: Omit<InjectInterruptOptions<TValue, TResult>, \"agentId\">\n  //     ): InterruptController<TValue, TResult>;\n  //\n  // The finding stands as a doc-ahead-of-release defect — the page carried no\n  // version note while the snippet was uncompilable — but it no longer blocks.\n  //\n  // human in the loop : inject interrupt start\n  // doc: injects \"default\" (the quickstart agent). The page shows no backend that emits an interrupt.\n  protected readonly controller = injectInterrupt<ReviewRequest>('default');\n  // human in the loop : inject interrupt end\n\n  protected asReviewRequest(value: unknown): ReviewRequest {\n    return typeof value === 'object' && value !== null\n      ? (value as ReviewRequest)\n      : {};\n  }\n\n  protected resolve(choiceId: string): void {\n    this.controller.resolve({ choiceId }).catch(() => undefined);\n  }\n\n  protected cancel(): void {\n    this.controller.cancel().catch(() => undefined);\n  }\n}\n// human in the loop : handle an interrupt end\n",
  "src/app/features/hitl/ticket-approval.component.ts": "// human in the loop : ticket approval start\r\n/**\r\n * \"Handle an interrupt from the store\", verbatim.\r\n * https://docs.copilotkit.ai/angular/openai-agents-python/human-in-the-loop/headless\r\n *\r\n * Verbatim, agent id \"ticketing\" included. HARNESS: no page registers a \"ticketing\" agent or shows a\r\n * backend that emits an interrupt; frontend/server.ts maps \"ticketing\" to the quickstart agent.\r\n */\r\n\r\nimport { Component } from '@angular/core';\r\nimport { injectAgentStore } from '@copilotkit/angular';\r\n\r\n@Component({\r\n  selector: 'app-ticket-approval',\r\n  template: `\r\n    @let interrupts = store().interruptController;\r\n\r\n    @if (interrupts.hasInterrupt()) {\r\n      <section>\r\n        <p>{{ interrupts.interrupt()?.message }}</p>\r\n        <button type=\"button\" (click)=\"interrupts.resolve({ approved: true })\">\r\n          Approve\r\n        </button>\r\n        <button type=\"button\" (click)=\"interrupts.cancel()\">Reject</button>\r\n      </section>\r\n    }\r\n  `,\r\n})\r\nexport class TicketApprovalComponent {\r\n  protected readonly store = injectAgentStore('ticketing');\r\n}\r\n// human in the loop : ticket approval end\r\n",
  "src/app/features/hitl/use-interrupt-chat.component.ts": "/**\n * HARNESS: Pausing the Agent for Input demo. The page's InterruptPanelComponent (verbatim) above a chat.\n * The page shows no backend that pauses; panel + chat use the quickstart `default` agent,\n * which is what the doc's injectInterrupt('default') watches.\n * https://docs.copilotkit.ai/angular/openai-agents-python/human-in-the-loop/useInterrupt\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\nimport { InterruptPanelComponent } from './interrupt-panel.component';\n\n@Component({\n  selector: 'app-use-interrupt-chat',\n  imports: [CopilotChat, InterruptPanelComponent],\n  template: `\n    <div style=\"display: flex; flex-direction: column; height: 100%\">\n      <div style=\"padding: 0.75rem 1rem\"><app-interrupt-panel /></div>\n      <div style=\"flex: 1; min-height: 0\"><copilot-chat /></div>\n    </div>\n  `,\n})\nexport class UseInterruptChatComponent {}\n",
  "src/app/features/inspector/inspector-chat.component.ts": "/**\n * A chat, so the Inspector has something to inspect.\n * https://docs.copilotkit.ai/angular/ag2/inspector\n *\n * Nothing here mounts the Inspector, and that is the page's whole point:\n * `@copilotkit/angular` mounts it for you — the `CopilotKit` service creates\n * `cpk-web-inspector`, supplies the application's core, and appends it to\n * `document.body` after the first browser render. The chat exists because\n * something has to inject that service; a notes route with no CopilotKit\n * consumer on it never constructs one, and so never gets a launcher.\n *\n * The page is emphatic that a hand-written mount must be deleted rather than\n * left alongside it: the framework reuses an existing `cpk-web-inspector`, but\n * a hand-rolled component's `DestroyRef.onDestroy` removes that element\n * unconditionally, so a route change tears out the Inspector the framework is\n * driving and it does not return without a full reload. This repo has never had\n * one, so there was nothing to retract.\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-inspector-chat',\n  imports: [CopilotChat],\n  template: `\n    <div style=\"height: 100%\">\n      <copilot-chat />\n    </div>\n  `,\n})\nexport class InspectorChatComponent {}\n",
  "src/app/features/mcp-apps/app.config.ts": "// src/app/app.config.ts on the MCP Apps page, verbatim except the runtime URL.\n// https://docs.copilotkit.ai/angular/openai-agents-python/generative-ui/mcp-apps\n// HARNESS: mounted as the providers of the mcp-apps/demo route (app.routes.ts), not the app root,\n// so the other pages keep their own provider.\nimport { ApplicationConfig } from \"@angular/core\";\nimport { provideCopilotKit } from \"@copilotkit/angular\";\nimport { provideMCPApps } from \"@copilotkit/angular/mcp-apps\";\n\nexport const appConfig: ApplicationConfig = {\n  providers: [\n    provideCopilotKit({ runtimeUrl: \"http://localhost:8290/api/copilotkit\" }), // HARNESS: doc says \"/api/copilotkit\" (relative, ng serve has no proxy); runtime on 8290\n    provideMCPApps(),\n  ],\n};\n",
  "src/app/features/mcp-apps/mcp-apps-chat.component.ts": "/**\n * MCP Apps demo: a plain chat under the page's provider (mcp-apps/app.config.ts, route providers).\n * The page gives no MCP server, no runtime `mcpApps` config and no agent change, so nothing here\n * can return an app resource.\n * https://docs.copilotkit.ai/angular/openai-agents-python/generative-ui/mcp-apps\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-mcp-apps-chat',\n  imports: [CopilotChat],\n  template: `<div style=\"height: 100%\"><copilot-chat /></div>`,\n})\nexport class McpAppsChatComponent {}\n",
  "src/app/features/media/voice-chat.component.ts": "// voice : accept voice input start\r\n/**\r\n * Voice page (docs.copilotkit.ai/angular/openai-agents-python/voice), verbatim:\r\n * \"No component option is required to display the microphone\", so the chat is a\r\n * plain `CopilotChat`; the mic shows only once the runtime has a transcription\r\n * service. The page's \"Voice backend setup\" link opens the generic /voice page, whose Backend\r\n * section (Next.js route + transcription service) is ported in frontend/server.ts under /voice.\r\n * The page's one TypeScript block, `registerRenderToolCall` for `getWeather`, is\r\n * called from the component's injection context as the page says.\r\n */\r\nimport { Component, inject } from '@angular/core';\r\nimport { CopilotChat, CopilotKit, registerRenderToolCall } from '@copilotkit/angular'; // HARNESS: the snippet has no imports\r\nimport { z } from 'zod'; // HARNESS: the snippet has no imports\r\n\r\nimport { WeatherCardComponent } from '../gen-ui-tool-rendering/weather-card.component'; // HARNESS: \"the renderer from Render a tool result\"\r\n\r\n@Component({\r\n  selector: 'app-voice-chat',\r\n  imports: [CopilotChat],\r\n  template: `\r\n    <div style=\"height: 100%\">\r\n      <copilot-chat />\r\n    </div>\r\n  `,\r\n})\r\nexport class VoiceChatComponent {\r\n  constructor() {\r\n    // HARNESS: the generic /voice page's runtimeUrl=\"/api/copilotkit-voice\", on the runtime server (8290, /voice mount)\r\n    inject(CopilotKit).updateRuntime({ runtimeUrl: 'http://localhost:8290/voice/api/copilotkit-voice' });\r\n    // voice : register a renderer start\r\n    registerRenderToolCall({\r\n      name: \"getWeather\",\r\n      args: z.object({ city: z.string() }),\r\n      component: WeatherCardComponent,\r\n    });\r\n    // voice : register a renderer end\r\n  }\r\n}\r\n// voice : accept voice input end\r\n",
  "src/app/features/open-generative-ui/app.config.ts": "// src/app/app.config.ts on the Open Generative UI page, verbatim except the runtime URL.\n// https://docs.copilotkit.ai/angular/openai-agents-python/generative-ui/open-generative-ui\n// HARNESS: mounted as the providers of the open-generative-ui/demo route (app.routes.ts), not the\n// app root, so the other pages' agents don't all get the sandbox tool.\nimport { ApplicationConfig } from \"@angular/core\";\nimport {\n  provideCopilotKit,\n  type SandboxFunction,\n} from \"@copilotkit/angular\";\nimport { z } from \"zod\";\n\nconst dashboardFilterParameters = z.object({ filter: z.string() });\n\nconst setDashboardFilter: SandboxFunction = {\n  name: \"setDashboardFilter\",\n  description: \"Set the active dashboard filter\",\n  parameters: dashboardFilterParameters,\n  handler: async (args) => {\n    const { filter } = dashboardFilterParameters.parse(args);\n    sessionStorage.setItem(\"dashboard-filter\", filter);\n    return { applied: filter };\n  },\n};\n\nexport const appConfig: ApplicationConfig = {\n  providers: [\n    provideCopilotKit({\n      runtimeUrl: \"http://localhost:8290/api/copilotkit\", // HARNESS: doc says \"/api/copilotkit\" (relative, ng serve has no proxy); runtime on 8290\n      openGenerativeUI: {\n        sandboxFunctions: [setDashboardFilter],\n      },\n    }),\n  ],\n};\n",
  "src/app/features/open-generative-ui/open-gen-ui-chat.component.ts": "/**\n * Open Generative UI demo: a plain chat under the page's provider (open-generative-ui/app.config.ts,\n * route providers). https://docs.copilotkit.ai/angular/openai-agents-python/generative-ui/open-generative-ui\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-open-gen-ui-chat',\n  imports: [CopilotChat],\n  template: `<div style=\"height: 100%\"><copilot-chat /></div>`,\n})\nexport class OpenGenUiChatComponent {}\n",
  "src/app/features/quickstart/quickstart-chat.ts": "// quickstart : add the chat ui start\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-quickstart-chat',\n  imports: [CopilotChat],\n  template: `\n    <div style=\"height: 100vh\">\n      <copilot-chat />\n    </div>\n  `,\n})\nexport class QuickstartChat {}\n// quickstart : add the chat ui end\n",
  "src/app/features/shared-state/account-context.component.ts": "// shared state : send read-only application context start\n/**\n * \"Send read-only application context\", verbatim. The accessor form keeps the\n * signal reads reactive, so changing the timezone re-registers the context.\n * https://docs.copilotkit.ai/angular/openai-agents-python/shared-state/agent-readonly\n */\n\nimport { Component, signal } from '@angular/core';\nimport { connectAgentContext } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-account-context',\n  template: `\n    <button type=\"button\" (click)=\"timezone.set('Europe/London')\">\n      Use London time\n    </button>\n  `,\n})\nexport class AccountContextComponent {\n  readonly userName = signal('Ada');\n  readonly timezone = signal('America/Los_Angeles');\n\n  constructor() {\n    connectAgentContext(() => ({\n      description: 'Current account and timezone',\n      value: JSON.stringify({\n        userName: this.userName(),\n        timezone: this.timezone(),\n      }),\n    }));\n  }\n}\n// shared state : send read-only application context end\n",
  "src/app/features/shared-state/agent-readonly-chat.component.ts": "/**\n * HARNESS: Agent Read-Only Context demo host. The page's two components (verbatim) beside one chat.\n * https://docs.copilotkit.ai/angular/openai-agents-python/shared-state/agent-readonly\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\nimport { AccountContextComponent } from './account-context.component';\nimport { SelectionContextComponent } from './selection-context.component';\n\n@Component({\n  selector: 'app-agent-readonly-chat',\n  imports: [CopilotChat, AccountContextComponent, SelectionContextComponent],\n  template: `\n    <div style=\"display: flex; height: 100%; gap: 1rem\">\n      <div style=\"width: 20rem; overflow-y: auto; padding: 1rem\">\n        <app-account-context />\n        <app-selection-context />\n      </div>\n      <div style=\"flex: 1; min-width: 0\">\n        <copilot-chat />\n      </div>\n    </div>\n  `,\n})\nexport class AgentReadonlyChatComponent {}\n",
  "src/app/features/shared-state/selection-context.component.ts": "// shared state : bind context in a template start\n/**\n * \"Bind context in a template\", verbatim. The directive registers on first\n * render, so it must not be rendered before the context is complete.\n * https://docs.copilotkit.ai/angular/openai-agents-python/shared-state/agent-readonly\n */\n\nimport { Component, computed, signal } from '@angular/core';\nimport { CopilotKitAgentContext } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-selection-context',\n  imports: [CopilotKitAgentContext],\n  template: ` <div [copilotkitAgentContext]=\"selectionContext()\"></div> `,\n})\nexport class SelectionContextComponent {\n  readonly selectedId = signal('record-42');\n  readonly selectionContext = computed(() => ({\n    description: 'The record selected in the application',\n    value: this.selectedId(),\n  }));\n}\n// shared state : bind context in a template end\n",
  "src/app/features/shared-state/shared-state-chat.component.ts": "// shared state : shared state chat start\n/**\n * HARNESS: Shared State demo host. The page's WorkspaceComponent (verbatim) beside one chat on the\n * same \"default\" agent (the page says to scope the store to the chat's agent id, shows no chat).\n * https://docs.copilotkit.ai/angular/openai-agents-python/shared-state\n */\n\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\nimport { WorkspaceComponent } from './workspace.component';\n\n@Component({\n  selector: 'app-shared-state-chat',\n  imports: [CopilotChat, WorkspaceComponent],\n  template: `\n    <div style=\"display: flex; height: 100%; gap: 1rem\">\n      <div style=\"width: 20rem; overflow-y: auto; padding: 1rem\">\n        <app-workspace />\n      </div>\n      <div style=\"flex: 1; min-width: 0\">\n        <copilot-chat />\n      </div>\n    </div>\n  `,\n})\nexport class SharedStateChatComponent {}\n// shared state : shared state chat end\n",
  "src/app/features/shared-state/workspace.component.ts": "// shared state : read and write agent state start\n/**\n * \"Read agent state\", verbatim. Reads through `store().state()` so Angular\n * tracks changes; writes through the plain AG-UI agent at `store().agent`.\n * https://docs.copilotkit.ai/angular/openai-agents-python/shared-state\n */\n\nimport { Component, computed } from '@angular/core';\nimport { injectAgentStore } from '@copilotkit/angular';\n\ntype WorkspaceState = {\n  notes: string[];\n  priority: 'low' | 'normal' | 'high';\n};\n\nconst EMPTY_STATE: WorkspaceState = {\n  notes: [],\n  priority: 'normal',\n};\n\n@Component({\n  selector: 'app-workspace',\n  template: `\n    <p>Priority: {{ state().priority }}</p>\n    <ul>\n      @for (note of state().notes; track note) {\n        <li>{{ note }}</li>\n      }\n    </ul>\n    <button type=\"button\" (click)=\"setPriority('high')\">\n      Mark high priority\n    </button>\n  `,\n})\nexport class WorkspaceComponent {\n  readonly store = injectAgentStore('default');\n  readonly state = computed(\n    () => (this.store().state() as WorkspaceState | undefined) ?? EMPTY_STATE,\n  );\n\n  protected setPriority(priority: WorkspaceState['priority']): void {\n    const agent = this.store().agent;\n    const current = (agent.state as WorkspaceState | undefined) ?? EMPTY_STATE;\n    agent.setState({ ...current, priority });\n  }\n}\n// shared state : read and write agent state end\n",
  "src/app/features/subagents/subagents-chat.component.ts": "/**\n * HARNESS: Sub-agents demo host. The page's Angular snippet is a fragment of a Showcase class\n * (`readDelegations`, `subAgentRendererConfig`, `SubAgentName`, `this.agentId`, `this.feature` are never\n * defined; kept verbatim in doc-verbatim/multi-agent-subagents/), so this delegation log is written by the\n * harness: it reads the `delegations` slot of the \"subagents\" agent's state, the slot the page's verbatim\n * subagents.py writes (backend/demo_agents/subagents.py, served by backend/agent_server.py on 8291 at /subagents).\n */\nimport { Component, computed } from '@angular/core';\nimport { CopilotChat, injectAgentStore } from '@copilotkit/angular';\n\ntype Delegation = { id: string; sub_agent: string; task: string; status: string; result: string };\n\n@Component({\n  selector: 'app-subagents-chat',\n  imports: [CopilotChat],\n  template: `\n    <div style=\"display: flex; height: 100%\">\n      <section style=\"width: 22rem; padding: 1rem; border-right: 1px solid #e2e8f0; overflow: auto\">\n        <h3 style=\"font-weight: 600\">Delegation log</h3>\n        @for (d of delegations(); track d.id) {\n          <article class=\"delegation\" style=\"margin-top: 0.75rem\">\n            <p style=\"font-weight: 600\">{{ d.sub_agent }} · {{ d.status }}</p>\n            <p style=\"color: #475569; font-size: 0.85rem\">{{ d.task }}</p>\n          </article>\n        } @empty {\n          <p style=\"color: #64748b\">No delegations yet.</p>\n        }\n      </section>\n      <div style=\"flex: 1; min-width: 0\"><copilot-chat agentId=\"subagents\" /></div>\n    </div>\n  `,\n})\nexport class SubagentsChatComponent {\n  private readonly agentStore = injectAgentStore('subagents');\n  protected readonly delegations = computed( // HARNESS: the delegation log the page never shows (readDelegations is undefined)\n    () => ((this.agentStore().state() as { delegations?: Delegation[] } | undefined)?.delegations ?? []),\n  );\n}\n",
  "src/app/features/threads/conversations.component.ts": "// threads : threads drawer and chat start\n/**\n * The drawer-plus-chat sample, verbatim. Both sit under one\n * `provideCopilotChatConfiguration`, which is what makes selection and\n * new-thread actions in the drawer update the chat.\n * https://docs.copilotkit.ai/angular/ag2/guides/threads-memory-attachments-headless\n */\n\nimport { Component } from '@angular/core';\nimport {\n  CopilotChat,\n  CopilotThreadsDrawer,\n  provideCopilotChatConfiguration,\n} from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-conversations',\n  imports: [CopilotChat, CopilotThreadsDrawer],\n  providers: [provideCopilotChatConfiguration({ agentId: 'support' })],\n  template: `\n    <copilot-threads-drawer agentId=\"support\" [limit]=\"20\" />\n    <copilot-chat />\n  `,\n})\nexport class ConversationsComponent {}\n// threads : threads drawer and chat end\n",
  "src/app/features/threads/thread-list.component.ts": "// threads : custom thread list start\n/**\n * \"For a custom thread list, use injectThreads\", verbatim.\n * https://docs.copilotkit.ai/angular/ag2/guides/threads-memory-attachments-headless\n */\n\nimport { Component } from '@angular/core';\nimport { injectThreads } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-thread-list',\n  template: `\n    <button type=\"button\" (click)=\"threads.startNewThread()\">\n      New conversation\n    </button>\n\n    @if (threads.isLoading()) {\n      <p>Loading conversations…</p>\n    } @else {\n      @for (thread of threads.threads(); track thread.id) {\n        <button type=\"button\" (click)=\"select(thread.id)\">\n          {{ thread.name ?? \"Untitled conversation\" }}\n        </button>\n      }\n    }\n\n    @if (threads.listError()) {\n      <button type=\"button\" (click)=\"threads.refetchThreads()\">Retry</button>\n    }\n  `,\n})\nexport class ThreadListComponent {\n  // threads : inject threads start\n  readonly threads = injectThreads({\n    agentId: 'support',\n    limit: 20,\n  });\n  // threads : inject threads end\n\n  protected select(threadId: string): void {\n    // Store this id and bind it to CopilotChat's threadId input.\n    console.log(threadId);\n  }\n}\n// threads : custom thread list end\n",
  "src/app/features/threads/threads-drawer-demo.component.ts": "/** HARNESS host: the Threads Drawer page's verbatim ConversationsComponent, full height. */\nimport { Component, inject } from '@angular/core';\nimport { CopilotKit } from '@copilotkit/angular';\n\nimport { ConversationsComponent } from './conversations.component';\n\n@Component({\n  selector: 'app-threads-drawer-demo',\n  imports: [ConversationsComponent],\n  // HARNESS: the page's template has no layout; the host is a flex row so the chat sits beside the drawer, not below the fold\n  template: `<div class=\"drawer-host\" style=\"display: flex; height: 100%\"><app-conversations style=\"display: flex; flex: 1; min-width: 0; height: 100%\" /></div>`,\n  styles: [`:host ::ng-deep .drawer-host copilot-chat { flex: 1; min-width: 0; }`],\n})\nexport class ThreadsDrawerDemoComponent {\n  constructor() {\n    // HARNESS: the page never says threads need a CopilotKit Intelligence runtime; frontend/server.ts serves one under /threads.\n    inject(CopilotKit).updateRuntime({ runtimeUrl: 'http://localhost:8290/threads/api/copilotkit' });\n  }\n}\n",
  "src/app/features/tools/frontend-tools-chat.component.ts": "/**\n * Frontend Tools demo: `registerFrontendTool(createBackgroundTool(background))`, as the page says,\n * from a component; the agent's `change_background` call sets the gradient behind the chat.\n * https://docs.copilotkit.ai/angular/openai-agents-python/frontend-tools\n */\nimport { Component, signal } from '@angular/core'; // HARNESS: the page never shows the host component\nimport { CopilotChat, registerFrontendTool } from '@copilotkit/angular'; // HARNESS: no imports on the page\n\nimport { DEFAULT_BACKGROUND, createBackgroundTool } from './tool-feature-model';\n\n@Component({\n  selector: 'app-frontend-tools-chat',\n  imports: [CopilotChat],\n  template: `\n    <div\n      data-testid=\"background-host\"\n      style=\"height: 100%; padding: 0.75rem; transition: background 400ms ease\"\n      [style.background]=\"background()\"\n    >\n      <div style=\"height: 100%; background: white; border-radius: 0.75rem; overflow: hidden\">\n        <copilot-chat />\n      </div>\n    </div>\n  `,\n})\nexport class FrontendToolsChatComponent {\n  /** Written by the agent through the change_background handler. HARNESS: the page's writable signal. */\n  protected readonly background = signal(DEFAULT_BACKGROUND);\n\n  constructor() {\n    // frontend tools : register a browser tool start\n    registerFrontendTool(createBackgroundTool(this.background));\n    // frontend tools : register a browser tool end\n  }\n}\n",
  "src/app/features/tools/tool-feature-model.ts": "// frontend tools : register a browser tool (change_background) start\n/**\n * The guide's `change_background` frontend tool.\n * https://docs.copilotkit.ai/angular/openai-agents-python/frontend-tools\n *\n * `createBackgroundTool` is the guide's function, unchanged. Everything above\n * it is not in the guide: the snippet is quoted from the live Showcase without\n * its `BackgroundToolArgs` type, its `resolveGradient` helper, or its imports,\n * so those are defined here to make it runnable.\n */\n\nimport { type WritableSignal } from '@angular/core'; // HARNESS: the snippet has no imports\nimport { type FrontendToolConfig } from '@copilotkit/angular'; // HARNESS: the snippet has no imports\nimport { z } from 'zod'; // HARNESS: the snippet has no imports\n\n/** Arguments the agent may send to `change_background`. */\nexport type BackgroundToolArgs = { // HARNESS: used by the snippet, never defined on the page\n  background?: string;\n  color?: string;\n};\n\n/** Named presets so the agent can ask for a look without writing CSS. */\nconst GRADIENT_PRESETS: Record<string, string> = {\n  blue: 'linear-gradient(180deg, #0c4a6e 0%, #38bdf8 100%)',\n  violet: 'linear-gradient(180deg, #4c1d95 0%, #c084fc 100%)',\n  sunset: 'linear-gradient(180deg, #f97316 0%, #db2777 55%, #7c3aed 100%)',\n  forest: 'linear-gradient(180deg, #14532d 0%, #4ade80 100%)',\n  slate: 'linear-gradient(180deg, #0f172a 0%, #475569 100%)',\n};\n\nexport const DEFAULT_BACKGROUND = GRADIENT_PRESETS['slate'];\n\n/**\n * Accept a preset name, a bare CSS color, or a full gradient and always return\n * something safe to drop into a `background` style binding.\n */\nexport function resolveGradient(value: string | undefined): string { // HARNESS: called by the snippet, never defined on the page\n  const raw = value?.trim();\n  if (!raw) {\n    return DEFAULT_BACKGROUND;\n  }\n\n  const preset = GRADIENT_PRESETS[raw.toLowerCase()];\n  if (preset) {\n    return preset;\n  }\n\n  return raw.includes('gradient(')\n    ? raw\n    : `linear-gradient(180deg, ${raw} 0%, ${raw} 100%)`;\n}\n\n/** Create the frontend tool that applies a requested CSS gradient. */\nexport function createBackgroundTool(\n  background: WritableSignal<string>,\n): FrontendToolConfig<BackgroundToolArgs> {\n  return {\n    name: \"change_background\",\n    description: \"Change the application background to a CSS gradient.\",\n    parameters: z.object({\n      background: z.string().optional(),\n      color: z.string().optional(),\n    }),\n    handler: async (args) => {\n      const next = resolveGradient(args.background ?? args.color);\n      background.set(next);\n      return { background: next };\n    },\n  };\n}\n// frontend tools : register a browser tool (change_background) end\n",
  "src/app/features/webmcp/order-search.component.ts": "import { Component } from \"@angular/core\";\nimport { registerFrontendTool } from \"@copilotkit/angular\";\nimport { z } from \"zod\";\n\n@Component({\n  selector: \"app-order-search\",\n  standalone: true,\n  template: \"\",\n})\nexport class OrderSearchComponent {\n  constructor() {\n    registerFrontendTool({\n      name: \"searchOrders\",\n      description: \"Search the signed-in user's orders by status\",\n      parameters: z.object({\n        status: z.enum([\"open\", \"shipped\", \"delivered\"]),\n      }),\n      handler: async ({ status }) => {\n        const orders = await searchOrders(status);\n        return JSON.stringify(orders);\n      },\n      webmcp: {\n        annotations: {\n          readOnlyHint: true,\n        },\n      },\n    });\n  }\n}\n\n// HARNESS: the WebMCP page calls searchOrders() but never defines it (FINDINGS: undefined helper).\n// Minimal stand-in so the page compiles; returns fake orders for the given status.\nasync function searchOrders(status: string) {\n  (window as unknown as { __searchOrdersCalls?: string[] }).__searchOrdersCalls = [...((window as unknown as { __searchOrdersCalls?: string[] }).__searchOrdersCalls ?? []), status]; // HARNESS: lets the recorder see the handler ran\n  return [{ id: \"ORD-1001\", status }];\n}\n",
  "src/app/features/webmcp/webmcp-chat.component.ts": "/**\n * HARNESS: WebMCP demo host: the page's OrderSearchComponent (registers searchOrders with webmcp on)\n * beside a chat on the default agent, so the same handler can be called by the CopilotKit agent.\n * https://docs.copilotkit.ai/angular/openai-agents-python/webmcp\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\nimport { OrderSearchComponent } from './order-search.component';\n\n@Component({\n  selector: 'app-webmcp-chat',\n  imports: [CopilotChat, OrderSearchComponent],\n  template: `<app-order-search /><div style=\"height: 100%\"><copilot-chat /></div>`,\n})\nexport class WebmcpChatComponent {}\n",
  "../frontend-headless/src/app/features/headless/headless-chat.component.ts": "// headless : build a headless chat start\n/**\n * \"Build a headless chat\", verbatim. No CopilotKit chrome: the transcript and\n * composer are hand-written over `injectAgentStore`, and the run is driven\n * through `CopilotKitCore.runAgent`.\n * https://docs.copilotkit.ai/angular/ag2/guides/threads-memory-attachments-headless\n */\n\nimport { Component, inject, signal } from '@angular/core';\nimport { CopilotKit, injectAgentStore } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-headless-chat',\n  template: `\n    <div aria-live=\"polite\">\n      @for (message of store().messages(); track message.id) {\n        <article [attr.data-role]=\"message.role\">\n          {{ message.content }}\n        </article>\n      }\n      @if (store().isRunning()) {\n        <p>Agent is working…</p>\n      }\n    </div>\n\n    <textarea\n      aria-label=\"Message\"\n      [value]=\"draft()\"\n      (input)=\"updateDraft($event)\"\n    ></textarea>\n    <button\n      type=\"button\"\n      [disabled]=\"store().isRunning() || !draft().trim()\"\n      (click)=\"send()\"\n    >\n      Send\n    </button>\n  `,\n})\nexport class HeadlessChatComponent {\n  private readonly copilotKit = inject(CopilotKit);\n  // headless : inject agent store start\n  readonly store = injectAgentStore('default');\n  // headless : inject agent store end\n  readonly draft = signal('');\n\n  protected updateDraft(event: Event): void {\n    this.draft.set((event.target as HTMLTextAreaElement).value);\n  }\n\n  protected async send(): Promise<void> {\n    const content = this.draft().trim();\n    if (!content || this.store().isRunning()) return;\n\n    const agent = this.store().agent;\n    agent.addMessage({\n      id: crypto.randomUUID(),\n      role: 'user',\n      content,\n    });\n    this.draft.set('');\n    // headless : run agent start\n    await this.copilotKit.core.runAgent({ agent });\n    // headless : run agent end\n  }\n}\n// headless : build a headless chat end\n",
  "../backend/pyproject.toml": "[project]\nname = \"agent-server\"\nversion = \"0.1.0\"\nrequires-python = \">=3.10\"\n# Doc (quickstart \"Install the SDK\" + Sub-agents step 1): pip install ag-ui-openai-agents openai-agents\ndependencies = [\n    \"ag-ui-openai-agents\",\n    \"openai-agents\",\n    # HARNESS: agent_server.py builds a FastAPI app and needs a server to run it; the page never installs either.\n    \"fastapi\",\n    \"uvicorn\",\n    \"httpx\",\n]\n",
  "../backend/.env.example": "# HARNESS: copy to backend/.env. The quickstart says the SDK's default OpenAI client reads OPENAI_API_KEY.\nOPENAI_API_KEY=\n",
};

export function readSource(path: string): string {
  return SOURCES[path] ?? `// Source not generated for ${path}. Run: npm run gen:sources`;
}
